local config = {
  ui_story_31000101_1_dialog_content = "¿Ah? ¿Me llamaste?",
  ui_story_31000101_2_dialog_content = "Todavía me estoy acostumbrando a que me llamen simplón...",
  ui_story_31000101_3_dialog_content = "Eso no es un problema. Tienes un cerebro un poco más grande que esos paramecios, así que seguro que te acostumbrarás.",
  ui_story_31000101_4_dialog_content = "¿Podría ser que tal vez, posiblemente, quizá me estás alabando?",
