  ui_story_31000101_6_dialog_content = "Por eso quería hablar contigo.",
  ui_story_31000101_7_dialog_content = "Estoy de acuerdo con sólo hablar.",
  ui_story_31000101_8_dialog_content = "Pero haz dicho que cuente una historia... Y no se me ocurre ninguna historia propia que contar.",
