  ui_story_31000101_19_option_content = "¡Yo soy la verdad!",
  ui_story_31000101_20_dialog_content = "¿Tú?",
  ui_story_31000101_21_dialog_content = "Ya veo. Sé que Dama Victoria piensa que eres algo especial, pero no eres exac. lo que yo llamaría mi verdad ideal.",
  ui_story_31000101_22_dialog_content = "Tal vez no estés viendo detenidamente.",
  ui_story_31000101_23_dialog_content = "Olvídalo... Cambiemos de tema. ¿Qué opinas de las tumbas y sus tesoros?",
  ui_story_31000101_24_dialog_content = "¡Suena interesante!",
  ui_story_31000101_25_dialog_content = "Así es, brillante y sin precio...",
