  ui_story_31000101_27_dialog_content = "No eres sólo tú, mi pequeño simplón. Muchas personas se interesan por estos tesoros.",
  ui_story_31000101_28_dialog_content = "Conocí a una persona así, que se colaba en estas tumbas para robar los tesoros que contenían.",
  ui_story_31000101_29_dialog_content = "¿Ah? ¿Un saq. de tumbas?",
  ui_story_31000101_30_dialog_content = "Así es. Andar a hurtadillas con un saco de premios, intentar entrar a tumbas y hacer una limpieza.",
  ui_story_31000101_31_dialog_content = "Al encontrarnos, estaba tan asustado que casi se desmaya.",
  ui_story_31000101_32_dialog_content = "Para un ladrón, dar contigo es esencialmente como dar con la policía...",
  ui_story_31000101_33_dialog_content = "¿Lo arrestaste?",
  ui_story_31000101_34_dialog_content = "¿Arrestarlo?",
  ui_story_31000101_35_dialog_content = "No tuve tiempo...",
  ui_story_31000101_36_dialog_content = "Sólo quería que me contara sus historias durante diez días y diez noches.",
  ui_story_31000101_37_option_content = "¿Tuviste tiempo de esc. sus cuentos?",
  ui_story_31000101_38_dialog_content = "No es como que tuv. otra cosa que hacer en esa tumba.",
  ui_story_31000101_39_dialog_content = "Quería saber más, sobre el mundo exterior, el cielo siempre cambiante, los árboles que mudan sus hojas, y...",
