  ui_story_31000101_42_option_content = "¿Los dos pasaron diez días y diez noches juntos en una tumba?",
  ui_story_31000101_43_dialog_content = "Sí. No fue lo sufi. largo.",
  ui_story_31000101_44_dialog_content = "Si no se hubiera quedado sin cosas que decir, me habría quedado aún más tiempo.",
  ui_story_31000101_45_dialog_content = "Lamen., terminó todas las historias que conocía, y eso fue el final.",
  ui_story_31000101_46_dialog_content = "Te encanta escuchar a la gente contar historias, ¿verdad Sikare Dantes?",
  ui_story_31000101_47_dialog_content = "(De repente siento la soledad de Sikare Dantes...)",
  ui_story_31000101_48_dialog_content = "¿Qué pasa, mi pequeña simplona? ¿Qué pasa con esa expresión de repente?",
  ui_story_31000101_49_dialog_content = "Oh, no es nada. De las historias que escuchaste durante esos diez días y noches, ¿cuál fue tu favorita?",
  ui_story_31000101_50_dialog_content = "¡Oh, había tantas!",
  ui_story_31000101_51_dialog_content = "Una de las historias trataba de una vez que se perdió en Northland.",
  ui_story_31000101_52_dialog_content = "Dijo que se encontró con una nevada allí.",
  ui_story_31000101_53_dialog_content = "Para salir de la nieve, siguió caminando contra el viento cortante, y finalmente entró en un bosque.",
  ui_story_31000101_54_dialog_content = "No podía ver el cielo por los árboles, y no podía identificar una dirección de la otra, por lo que marcó el terreno para no vagar sin rumbo.",
  ui_story_31000101_55_dialog_content = "Pero después de caminar mucho tiempo... De repente vio una marca que había hecho antes en el camino frente a él.",
  ui_story_31000101_56_dialog_content = "¡Whoa! ¿¡Comenzó a ir en círculos!?",
  ui_story_31000101_57_dialog_content = "No... Según él, no dobló ni una sola esquina, y se dirigió en línea recta todo el tiempo.",
  ui_story_31000101_58_dialog_content = "Es más, cuando por fin se dio cuenta, descubrió que había algo más que marcas en la carretera frente a él... Encontró sus marcas a la izquierda, derecha y detrás de él.",
  ui_story_31000101_59_dialog_content = "Qué... ¡espeluznante!",
  ui_story_31000101_60_dialog_content = "Mucho. Cuando escuché esto, estaba muy asustado como para soltar el esqueleto de la tumba.",
  ui_story_31000101_61_dialog_content = "Urgh... Intenta abrazar otra cosa la próx. vez...",
  ui_story_31000101_62_dialog_content = "Pero, de repente, vio que el árbol que tenía delante se agitaba y surgía una pequeña figura.",
  ui_story_31000101_63_dialog_content = "Pensó que era un Eclipsite... Pero pronto descubrió que era un niño.",
  ui_story_31000101_64_dialog_content = "Un niño encantador con la cara roja y grandes ojos que le miraban fijamente.",
  ui_story_31000101_65_dialog_content = "El niño le preguntó si estaba perdido.",
  ui_story_31000101_66_dialog_content = "Dijo que sí, y una mirada de simpatía se extendió por el rostro del niño.",
  ui_story_31000101_67_option_content = "Este niño es tan... ¡sospechoso!",
  ui_story_31000101_68_dialog_content = "¡Eso es lo que pensé!",
  ui_story_31000101_69_option_content = "¿Ese niño era... una ilusión?",
  ui_story_31000101_70_dialog_content = "Eso mismo pensé yo.",
  ui_story_31000101_71_dialog_content = "Pero dijo que cuando el niño se enteró de que estaba perdido, se acercó a él y le tomó su mano.",
  ui_story_31000101_72_dialog_content = "Entonces el niño le dijo: \"Ven conmigo.\"",
  ui_story_31000101_73_dialog_content = "¿¡Qué!?",
  ui_story_31000101_74_dialog_content = "¡Es impactante, lo sé!",
  ui_story_31000101_75_dialog_content = "Pero no tenía ninguna otra opción, así que siguió al niño.",
  ui_story_31000101_76_dialog_content = "Después de caminar una media hora, aparecieron las llanuras blancas como la nieve.",
  ui_story_31000101_77_dialog_content = "¡Lograron salir del bosque!",
  ui_story_31000101_78_dialog_content = "¡Sip!",
  ui_story_31000101_79_dialog_content = "Estaba muy agradecido y quería dar gracias al niño, pero cuando se dio la vuelta, el niño no aparecía por ninguna parte.",
  ui_story_31000101_80_dialog_content = "Sólo estaba el bosque detrás, la nieve delante, y sólo él, solo en aquella vasta tierra helada.",
  ui_story_31000101_81_dialog_content = "¡Qué his. tan extraña!",
  ui_story_31000101_82_dialog_content = "¿Y realmente no era una ilusión?",
  ui_story_31000101_83_dialog_content = "Lo fuera o no... No estaba seguro.",
  ui_story_31000101_84_dialog_content = "Sólo sabía que esta historia me gustaba mucho.",
  ui_story_31000101_85_dialog_content = "A cambio, le di algo que necesitaba.",
  ui_story_31000101_86_dialog_content = "Eso significa...",
  ui_story_31000101_87_dialog_content = "¿¡Tesoro!?",
  ui_story_31000101_88_dialog_content = "Correcto. Suficiente para mantenerlo cómodo por el resto de su vida.",
  ui_story_31000101_89_dialog_content = "No, no sólo para mantenerlo cómodo. Es posible que haya usado el tesoro para alcanzar alturas mayores que la mayoría de la gente podría soñar.",
  ui_story_31000101_90_dialog_content = "¿¡Tanto, eh!?",
  ui_story_31000101_91_dialog_content = "Si hubiera sabido que podía obtener una recompensa por contarte una historia, ¡te habría contado una hace años!",
  ui_story_31000101_92_dialog_content = "¿Arrepentida de tu tontería, mi pequeña simplona?",
  ui_story_31000101_93_dialog_content = "Pero tal vez no querrías el tesoro que le di, mi pequeña simplona.",
  ui_story_31000101_94_dialog_content = "¿Ah? ¿Qué clase de extraño tesoro le diste?",
  ui_story_31000101_95_dialog_content = "Alto, es decir, el tesoro de la tumba estaba maldito, así que...",
  ui_story_31000101_96_dialog_content = "Por favor, no uses ese tipo de raz. simple, como lo haría un paramecia común.",
  ui_story_31000101_97_dialog_content = "Le di un tesoro más allá del dinero, del tiempo, de los confines de la propia civilización...",
  ui_story_31000101_98_dialog_content = "Le di los secretos de la verdad.",
  ui_story_31000101_99_option_content = "¿Le predicaste?",
  ui_story_31000101_100_dialog_content = "La verdad debe regalarse a la persona que la merece. Y él se lo merece.",
  ui_story_31000101_101_option_content = "Ent., ¿lo mataste?",
  ui_story_31000101_102_dialog_content = "La muerte podía ser una forma de apreciar y conv. en la verdad, pero no la nec. entonces.",
  ui_story_31000101_103_dialog_content = "Le di el libro sag. de True Order. Porque él me enseñó el mundo durante diez días y diez noches, yo le enseñé la verdad durante diez días y diez noches.",
  ui_story_31000101_104_dialog_content = "Escuchándote hablar de la verdad durante diez días y diez noches... ¿Ese chico sigue vivo?",
  ui_story_31000101_105_dialog_content = "Como dije antes, debe estar viviendo bien.",
  ui_story_31000101_106_dialog_content = "No sólo eso, después de aceptar la verdad tras diez días y diez noches, llegó a una epifanía.",
  ui_story_31000101_107_dialog_content = "Desde entonces, se convirtió en el difusor de la verdad, llevando el evangelio de la verdad a la gente de toda Astra.",
  ui_story_31000101_108_dialog_content = "Además, es un muy buen narrador...",
  ui_story_31000101_109_dialog_content = "Claro. En fin, te contó historias durante diez días y diez noches...",
  ui_story_31000101_110_dialog_content = "Por eso su interpretación de la verdad ha sido alabada por tanta gente.",
  ui_story_31000101_111_dialog_content = "Ha recibido un gran apoyo y se le ha pedido que difunda la verdad por todo el mundo. Por supuesto, también se le ha proporcionado comida y alojamiento a cambio.",
  ui_story_31000101_112_dialog_content = "Así que ya no tiene preocupación por estar cómodo.",
  ui_story_31000101_113_dialog_content = "Como divulgador de la verdad, está muy por encima del nivel de simples mortales y paramecios.",
  ui_story_31000101_114_dialog_content = "Bueno, supongo que le diste un tesoro muy preciado...",
  ui_story_31000101_115_dialog_content = "Comida, bebida y lugar para dormir... Hay mucha gente que sólo puede soñar con esos lujos.",
  ui_story_31000101_116_dialog_content = "Mi pequeña simplona, ¿sigues insistiendo en pensar como paramecios?",
  ui_story_31000101_117_dialog_content = "Te dije que no soy tan inteligente...",
  ui_story_31000101_118_dialog_content = "Bueno, puedes pensar en este punto por el momento.",
  ui_story_31000101_119_dialog_content = "Espera... ¿Qué es esa sonrisa pícara que tienes?",
  ui_story_31000601_1_dialog_content = "El tiempo ha estado bastante frío últimamente. No veo tanta gente por ahí, pero la clínica está tan ocupada como siempre.",
  ui_story_31000601_2_dialog_content = "Cada servicio tiene una enorme lista de espera, incluso la fila para recoger medicamentos es increíble.",
  ui_story_31000601_3_dialog_content = "¿De casualidad te estás quejando de acompañarme a la clínica?",
  ui_story_31000601_4_dialog_content = "¡N-En absoluto! Lo que quiero decir es que, con todos estos pacientes, el médico debe estar muy ocupado...",
  ui_story_31000601_5_dialog_content = "Tuviste mucha suerte, Sikare. Escuché que es fácil enfermarse cuando las estaciones comienzan a cambiar.",
  ui_story_31000601_6_dialog_content = "Gracias por su preocupación, pero no me enfermo tan fácilmente. Solo estoy aquí para recoger una receta para <color=#FFB400>insomnio</color>.",
  ui_story_31000601_7_dialog_content = "Aunque debo estar de acuerdo, no esperaba que la fila fuera tan larga...",
  ui_story_31000601_8_dialog_content = "Parece que estaremos aquí por bastante tiempo, así que si realmente desea quejarse, no tengo objeciones.",
  ui_story_31000601_9_option_content = "¿Insomnio? ¿Qué quieres decir?",
  ui_story_31000601_10_dialog_content = "Estoy mucho más preocupado por tu salud que por hacer cola, Sikare.",
  ui_story_31000601_11_option_content = "Esperaré contigo.",
  ui_story_31000601_12_dialog_content = "Acepté ir contigo a recoger la medicina, así que no habrá quejas de mi parte.",
  ui_story_31000601_13_dialog_content = "De todos modos, ¿mencionaste una receta para el insomnio?",
  ui_story_31000601_14_dialog_content = "¿Has estado perdiendo el sueño por algo últimamente?",
  ui_story_31000601_15_dialog_content = "... Je. Supongo que Lady Victoria tenía razón al considerarte con tanta estima.",
  ui_story_31000601_16_dialog_content = "Para obtener una cantidad adecuada de sueño reparador, necesito silencio total, pero las tumbas han estado bastante ruidosas últimamente.",
  ui_story_31000601_17_dialog_content = "¿Te refieres a la Cripta Estrellada?",
  ui_story_31000601_18_dialog_content = "No me digas que algo ha estado perturbando su sueño...",
  ui_story_31000601_19_dialog_content = "Tu conjetura podría muy bien ser cierta. Después de todo, estás entre los elegidos del Orden Verdadero.",
  ui_story_31000601_20_dialog_content = "Si es así, parece que tendré que estar más alerta para que no suceda algo terrible...",
  ui_story_31000601_21_dialog_content = "¡Se lo ruego, doctora! ¡Por favor, ayúdame!",
  ui_story_31000601_22_dialog_content = "¡Solo déjame explicarme una vez más, por favor!",
  ui_story_31000601_23_dialog_content = "Si no me ayudas, no tendré a quién acudir...",
  ui_story_31000601_24_dialog_content = "Lo siento mucho, señora.",
  ui_story_31000601_25_dialog_content = "Pero el doctor ya te dijo que no hay nada que pueda hacer. Tengo que pedirte que busques ayuda en otra parte.",
  ui_story_31000601_26_dialog_content = "Todavía hay un montón de <color=#FFB400>personas vivas que respiran</color> detrás de usted esperando recibir tratamiento del médico.",
  ui_story_31000601_27_dialog_content = "¿Por qué no vienes conmigo al vestíbulo y podemos sentarnos juntos hasta que te calmes? ¿Estaría bien?",
  ui_story_31000601_28_dialog_content = "Alguien está montando una escena al frente de la fila...",
  ui_story_31000601_29_dialog_content = "Parece que el médico simplemente no quiere tratar a esa señora, pero algo que dijo la enfermera me llamó la atención...",
  ui_story_31000601_30_dialog_content = "¿Qué quiso decir exactamente con <color=#FFB400>\"gente que vive y respira\"</color>?",
  ui_story_31000601_31_dialog_content = "Ah, aquí vienen.",
  ui_story_31000601_32_dialog_content = "...",
  ui_story_31000601_33_dialog_content = "Por favor... que alguien salve a mi hijo...",
  ui_story_31000601_34_dialog_content = "Toma asiento mientras te sirvo un vaso de agua.",
  ui_story_31000601_35_dialog_content = "¡No quiero agua! Quiero que alguien salve a mi hijo...",
  ui_story_31000601_36_dialog_content = "Eh... ¿Perdóneme, señorita? Perdón por interrumpir.",
  ui_story_31000601_37_dialog_content = "¿Puedo preguntar por qué el médico no está dispuesto a ayudar a esa señora? Se ve terriblemente angustiada...",
  ui_story_31000601_38_dialog_content = "Además, ¿podría explicar qué quiso decir con \"personas que viven y respiran\" en este momento?",
  ui_story_31000601_39_dialog_content = "Ha estado viniendo a la clínica temprano todas las mañanas durante los últimos días, rogándole al médico que salve a su hijo.",
  ui_story_31000601_40_dialog_content = "Pero cuando el médico le pregunta qué le pasa a su hijo, ella dice que ya está muerto.",
  ui_story_31000601_41_dialog_content = "Muerto...?",
  ui_story_31000601_42_dialog_content = "¿Así que sigue pidiéndole al médico... que salve a su hijo muerto?",
  ui_story_31000601_43_dialog_content = "Eso ciertamente explica su elección de palabras.",
  ui_story_31000601_44_dialog_content = "Puedo ver por qué el médico dice que no puede ayudar.",
  ui_story_31000601_45_dialog_content = "Además, dice que su hijo murió en una casa embrujada.",
  ui_story_31000601_46_dialog_content = "Ella quiere que el médico vaya a la casa encantada y examine su cadáver personalmente.",
  ui_story_31000601_47_dialog_content = "Pero...",
  ui_story_31000601_48_dialog_content = "No hay necesidad de ocultarnos ningún detalle. Solo dinos lo que sabes.",
  ui_story_31000601_49_dialog_content = "¡Todos dicen que la única razón por la que esa casa está embrujada es porque su hijo mató a sus amigos allí!",
  ui_story_31000601_50_dialog_content = "¿Será que quiere que el médico examine el cadáver de su hijo para probar su inocencia?",
  ui_story_31000601_51_dialog_content = "Me temo que tendrás que preguntárselo tú mismo. Solo me enteré de esto por escuchar los chismes de los otros pacientes.",
  ui_story_31000601_52_dialog_content = "Le haría un gran servicio a nuestra clínica si la ayudara a resolver su dilema.",
  ui_story_31000601_53_dialog_content = "¿M-Yo? Yo-yo solo tenía curiosidad acerca de su historia, ¡eso es todo! En cuanto a examinar un cadáver, yo... yo...",
  ui_story_31000601_54_dialog_content = "Le avisaré al doctor que estás en el caso. ¡Estoy seguro de que estará muy agradecido por tu ayuda!",
  ui_story_31000601_55_dialog_content = "¿Alguna vez has realizado una autopsia, Snowball?",
  ui_story_31000601_56_dialog_content = "N-Nunca...",
  ui_story_31000601_57_dialog_content = "Pero como ya sabemos mucho sobre el asunto, no creo que pueda dormir por la noche hasta que llegue al fondo del asunto.",
  ui_story_31000601_58_dialog_content = "¿Vas a ayudarla?",
  ui_story_31000601_59_dialog_content = "Sí... Aunque no tengo ni idea de por dónde empezar o encontrar un médico forense para hacer una autopsia...",
  ui_story_31000601_60_dialog_content = "Pero si lo que dijo la enfermera es cierto, no puedo quedarme de brazos cruzados y fingir que no escuché nada.",
  ui_story_31000601_61_dialog_content = "Solo viviré para arrepentirme si no ayudo a una madre a encontrar la paz después de perder a su hijo.",
  ui_story_31000601_62_dialog_content = "Je... Ese es el Snowball que siempre he conocido.",
  ui_story_31000601_63_dialog_content = "¿Disculpe, señorita?",
  ui_story_31000601_64_dialog_content = "¿Sí? ¿Puedo ayudarlo?",
  ui_story_31000601_65_dialog_content = "Tengo una petición para ti. Necesito... *susurrando*",
  ui_story_31000601_66_dialog_content = "Si puede conseguirme esas cosas, estaremos encantados de ayudarle con el problema de esa señora.",
  ui_story_31000601_67_dialog_content = "¡¿R-En serio?! ¡Por supuesto! Sólo un momento.",
  ui_story_31000601_68_dialog_content = "<color=#e8d9bb>Diez minutos tarde...</color>",
  ui_story_31000601_69_dialog_content = "¡¿S-Sikare?!",
  ui_story_31000601_70_dialog_content = "Menos mal que no me deshice del uniforme de esa doctora después de que se fue... ¡Te queda muy bien!",
  ui_story_31000601_71_dialog_content = "Este maletín tiene todos los instrumentos que podría pedir. Gracias por tu ayuda.",
  ui_story_31000601_72_dialog_content = "Mi placer. ¡Todos contamos con ustedes dos!",
  ui_story_31000601_73_dialog_content = "Espera... ¿Has sido médico todo este tiempo, Sikare?",
  ui_story_31000601_74_dialog_content = "Dependiendo de cómo definas a un médico... sí, podrías decir eso.",
  ui_story_31000601_75_dialog_content = "A diferencia del médico de esta clínica, me especializo en tratar a los muertos, no a los vivos.",
  ui_story_31000601_76_dialog_content = "Escuchar sus palabras y transmitirlas ha sido siempre mi deber.",
  ui_story_31000601_77_dialog_content = "Entonces significa que eres el perfecto <color=#FFB400>médico de los muertos</color> esa señora necesita ahora mismo!",
  ui_story_31000601_78_dialog_content = "Por eso decidiste ponerte el uniforme de doctora y ayudarme a resolver su problema, ¿verdad?",
  ui_story_31000601_79_dialog_content = "Por supuesto... A menos que tengas a alguien más en mente que esté dispuesto a realizar una autopsia en una casa embrujada.",
  ui_story_31000601_80_dialog_content = "Venir. Vamos a escuchar lo que tiene que decir.",
  ui_story_31000601_81_dialog_content = "¿Eh? Pero, ¿qué hay de recoger su medicina?",
  ui_story_31000601_82_dialog_content = "Algo me dice que este asunto está relacionado con la causa de mi insomnio.",
  ui_story_31000601_83_dialog_content = "Quizás al resolver sus problemas, el ruido alrededor de la cripta también cesará.",
  ui_story_31000601_84_dialog_content = "Muy bien, vamos a hablar con ella.",
  ui_story_31000601_85_dialog_content = "Por favor ayuda a mi hijo... Es inocente, te lo digo...",
  ui_story_31000601_86_dialog_content = "Él nunca mataría a alguien...",
  ui_story_31000601_87_dialog_content = "Hola señora. Esa enfermera nos habló de su situación.",
  ui_story_31000601_88_dialog_content = "Si no le importa, ¿podría contarnos más sobre lo que pasó con su hijo?",
  ui_story_31000601_89_dialog_content = "Creo que podríamos ayudarte a descubrir la verdad.",
  ui_story_31000601_90_dialog_content = "¿De... De verdad...?",
  ui_story_31000601_91_dialog_content = "Lo siento, pero ¿realmente eres médico? ¿Y estás realmente dispuesto a ayudarme?",
  ui_story_31000601_92_dialog_content = "¿Y si te digo que mi hijo ya está muerto? ¿Aún quieres ayudarme?",
  ui_story_31000601_93_dialog_content = "Por supuesto. Es precisamente por esta razón que estoy dispuesto a prestarte mi ayuda.",
  ui_story_31000601_94_dialog_content = "¡Oh, gracias a Dios!",
  ui_story_31000601_95_dialog_content = "¡Finalmente, alguien que está dispuesto a probar la inocencia de mi hijo!",
  ui_story_31000601_96_dialog_content = "¡Toma todo mi dinero! ¡Todos mis objetos de valor! ¡Pagaré lo que pidas, lo juro!",
  ui_story_31000601_97_dialog_content = "No necesito ni su dinero ni sus objetos de valor. No me sirven para nada.",
  ui_story_31000601_98_dialog_content = "No vas a... rechazarme, ¿verdad?",
  ui_story_31000601_99_dialog_content = "¡P-Por favor, no me malinterprete! Lo que quiere decir es que no necesita ningún tipo de compensación económica, ¡eso es todo!",
  ui_story_31000601_100_dialog_content = "Ya acordamos ayudarlo, y eso es exactamente lo que planeamos hacer.",
  ui_story_31000601_101_dialog_content = "Ahora, ¿podría contarnos más sobre su hijo y su situación, por favor?",
  ui_story_31000601_102_dialog_content = "¿Y por qué a la gente se le ocurrían rumores sobre él así en primer lugar?",
  ui_story_31000601_103_dialog_content = "Dejame empezar por el principio...",
  ui_story_31000601_104_dialog_content = "Hace tres días, mi hijo me dijo que sus amigos planeaban explorar una casa abandonada en las afueras del pueblo.",
  ui_story_31000601_105_dialog_content = "Pero como le preocupaba dejarme sola en casa, les dijo que no podía ir.",
  ui_story_31000601_106_dialog_content = "A la mañana siguiente, cuando se dio cuenta de que sus amigos no habían vuelto a casa, se preocupó.",
  ui_story_31000601_107_dialog_content = "Le dije que no se preocupara por mí y que fuera a buscar a sus amigos.",
  ui_story_31000601_108_dialog_content = "Esa fue la última vez que lo vi.",
  ui_story_31000601_109_dialog_content = "Han pasado tres días... Me temo que tu hijo y sus amigos han perecido dentro de la casa hace mucho tiempo.",
  ui_story_31000601_110_dialog_content = "Esperé toda la noche por él. Para la tarde del día siguiente, todavía no había vuelto a casa.",
  ui_story_31000601_111_dialog_content = "En ese momento, ya lo sabía. Mi hijo valoraba la amistad por encima de casi cualquier otra cosa, ya ves. Hubiera preferido morir a su lado que dejarlos atrás.",
  ui_story_31000601_112_dialog_content = "Pero nadie más ve eso. ¡En lugar de querer encontrar la verdad, lo acusaron de asesinar a sus amigos y calumniaron su buen nombre!",
  ui_story_31000601_113_dialog_content = "Parece estar más preocupado por la inocencia de su hijo que por las circunstancias de su muerte.",
  ui_story_31000601_114_dialog_content = "¿Es por eso que quiere que le hagan una autopsia?",
  ui_story_31000601_115_dialog_content = "También habíamos sido solo nosotros dos. Era la única familia que me quedaba.",
  ui_story_31000601_116_dialog_content = "No tienes idea de lo difícil que es para mí aceptar que se ha ido.",
  ui_story_31000601_117_dialog_content = "¡Pero lo estaría defraudando si no averiguo la verdad y limpio su nombre!",
  ui_story_31000601_118_dialog_content = "Sé que debo haberle causado a ese médico una gran cantidad de dolor, pero no sabía a quién más acudir...",
  ui_story_31000601_119_dialog_content = "No tengo experiencia médica, y el olor a sangre me marea tanto que ni siquiera puedo acercarme a esa casa...",
  ui_story_31000601_120_dialog_content = "Tengo muchas ganas de ayudarla, Sikare... También quiero saber la verdad detrás de esa casa encantada.",
  ui_story_31000601_121_dialog_content = "¿Y usted? ¿Le crees a ella?",
  ui_story_31000601_122_dialog_content = "no le creo a nadie Pongo mi confianza solo en <color=#FFB400>la verdad</color>.",
  ui_story_31000601_123_dialog_content = "En cuanto a <color=#FFB400>Verdad</color> escondido en este misterio... Solo encontraremos las respuestas que buscamos consultando a los espíritus de los muertos atrapados dentro de esa casa encantada.",
  ui_story_31000601_124_dialog_content = "Por favor, díganos dónde encontrar la casa.",
  ui_story_31000601_125_dialog_content = "Estoy tan aliviado de que estés dispuesto a ayudar.",
  ui_story_31000601_126_dialog_content = "Déjame llevarte allí de inmediato.",
  ui_story_31000601_127_dialog_content = "Una vez que descubramos la verdad, tal vez finalmente pueda llevarlo a casa...",
  ui_story_31000601_128_dialog_content = "Como desees.",
  ui_story_31000601_129_dialog_content = "No perdamos más tiempo. ¡Por favor, guía el camino!",
  ui_story_31000601_130_dialog_content = "Un poco más cerca y el olor a sangre será demasiado abrumador. Nos quedaremos aquí y te esperaremos, Sikare.",
  ui_story_31000601_131_dialog_content = "Muy bien. Debería estar bien por mi cuenta.",
  ui_story_31000601_132_dialog_content = "Por favor, descríbame la apariencia de su hijo. También necesitaré recolectar una muestra de sangre si no se opone.",
  ui_story_31000601_133_dialog_content = "Tenga la seguridad de que mi técnica es perfectamente sólida. No sacaré más sangre de la necesaria, y tú tampoco olerás nada.",
  ui_story_31000601_134_dialog_content = "Entiendo... Dejo todo en sus capaces manos, Doctor.",
  ui_story_31000601_135_dialog_content = "<color=#e8d9bb>Veinte minutos después...</color>",
  ui_story_31000601_136_dialog_content = "¿Cómo se veían las cosas allí, Sikare?",
  ui_story_31000601_137_dialog_content = "Espera... ¿No regresaste con nada más que tus herramientas médicas? ¿Significa eso que su hijo no estaba allí?",
  ui_story_31000601_138_dialog_content = "¿Estás diciendo que existe la posibilidad de que mi hijo esté... vivo?",
  ui_story_31000601_139_dialog_content = "Lo siento mucho, pero de hecho encontré los restos de su hijo dentro de la casa.",
  ui_story_31000601_140_dialog_content = "Debido a que su cadáver estaba apilado con muchos otros cuerpos, su tasa de descomposición fue anormalmente rápida.",
  ui_story_31000601_141_dialog_content = "Como resultado, no pude recuperar su cuerpo. Lo siento.",
  ui_story_31000601_142_dialog_content = "Está bien... Ya estoy más que agradecido de que estuvieras dispuesto a ayudar...",
  ui_story_31000601_143_dialog_content = "Todavía es demasiado pronto para agradecerme. Todavía tengo más para informar.",
  ui_story_31000601_144_dialog_content = "Aunque su cuerpo ya se había descompuesto considerablemente, pude usar su muestra de sangre para localizar algunos de sus huesos.",
  ui_story_31000601_145_dialog_content = "A través de esos huesos, pude escuchar susurros de <color=#FFB400>la verdad</color>.",
  ui_story_31000601_146_dialog_content = "<color=#e8d9bb>Hace tres días...</color>",
  ui_story_31000601_147_dialog_content = "Grr... Graaah...",
  ui_story_31000601_148_dialog_content = "Graaah...!",
  ui_story_31000601_149_dialog_content = "Oh no... ¿Están bien, chicos? ¡Dime que no es demasiado tarde!",
  ui_story_31000601_150_dialog_content = "¡¿Qué estás haciendo aquí?! ¡Fuera, date prisa! ¡Ahorrarse!",
  ui_story_31000601_151_dialog_content = "Si no hubiera sugerido explorar este lugar, no estaríamos hasta el cuello en Eclipsites...",
  ui_story_31000601_152_dialog_content = "No sé qué estáis haciendo aquí, pero ninguno de vosotros debería pagar por mi error.",
  ui_story_31000601_153_dialog_content = "¡Es por eso que me quedaré aquí y los detendré mientras el resto de ustedes huye! ¡Es lo menos que puedo hacer!",
  ui_story_31000601_154_dialog_content = "¿De verdad crees que soy el tipo de persona que dejaría morir a sus amigos?",
  ui_story_31000601_155_dialog_content = "Ya estoy aquí, ¿no? ¡No voy a volver solo, maldita sea!",
  ui_story_31000601_156_dialog_content = "Si mi mamá alguna vez descubriera que no valoro la vida de mis mejores amigos...",
  ui_story_31000601_157_dialog_content = "Bueno, no creo que ella esté muy contenta con eso.",
  ui_story_31000601_158_dialog_content = "Je... ¿Qué diablos vamos a hacer contigo?",
  ui_story_31000601_159_dialog_content = "Juro que lo compensaré con todos una vez que salgamos de aquí.",
  ui_story_31000601_160_dialog_content = "¡Decir ah! ¡Entonces haré lo que sea necesario para asegurarme de que cumplas tu palabra!",
  ui_story_31000601_161_dialog_content = "Graah!!",
  ui_story_31000601_162_dialog_content = "Greeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeen!!",
  ui_story_31000601_163_dialog_content = "Así que los Eclipsites los consiguieron...",
  ui_story_31000601_164_dialog_content = "Por cierto. Después de una breve búsqueda, pude encontrar varios cuerpos recientemente fallecidos... Creo que eran sus amigos.",
  ui_story_31000601_165_dialog_content = "Cada uno de ellos fue, sin duda, asesinado por Eclipsites.",
  ui_story_31000601_166_dialog_content = "Esto significa que mi hijo nunca fue un asesino...",
  ui_story_31000601_167_dialog_content = "Correcto. Además, según mi investigación, la hora de su muerte fue algo posterior a la de sus amigos.",
  ui_story_31000601_168_dialog_content = "Dado el estado roto de sus restos, parece que sufrió muchos más ataques que ellos.",
  ui_story_31000601_169_dialog_content = "Así que realmente aguantó hasta el final...",
  ui_story_31000601_170_dialog_content = "Siempre supe que mi hijo era un buen chico... Hizo todo lo que pudo...",
  ui_story_31000601_171_dialog_content = "Si esta fue la elección que hizo; si esto es lo que su corazón le dijo que hiciera... Entonces puedo aceptarlo.",
  ui_story_31000601_172_dialog_content = "Si existe tal cosa como la reencarnación, elegiría volver a ser su madre.",
  ui_story_31000601_173_dialog_content = "Gracias a los dos por su ayuda. Por favor, permíteme pagarte adecuadamente por tus problemas.",
  ui_story_31000601_174_dialog_content = "Estoy seguro de que mi hijo también querría esto.",
  ui_story_31000601_175_dialog_content = "Solo di tu precio, y haré todo lo que esté a mi alcance para cumplirlo.",
  ui_story_31000601_176_dialog_content = "Realmente no necesitamos pago, señora. Estábamos felices de—",
  ui_story_31000601_177_dialog_content = "Muy bien, pero sé que no hay vuelta atrás en tu palabra ahora.",
  ui_story_31000601_178_dialog_content = "S-Sikare! ¿No dijiste antes que solo te interesaba la verdad...?",
  ui_story_31000601_179_dialog_content = "No, está bastante bien; toda buena acción merece una recompensa. Por favor, dígame qué desea como pago.",
  ui_story_31000601_180_dialog_content = "Tome esta tarjeta de presentación. Me gustaría que se comunique con la persona que aparece en él y le diga la verdad sobre lo que sucedió aquí.",
  ui_story_31000601_181_dialog_content = "¿Ah?",
  ui_story_31000601_182_dialog_content = "Ella es una periodista excepcionalmente profesional y confiable que dará a conocer la verdad a todos, no solo a nosotros.",
  ui_story_31000601_183_dialog_content = "Esto... Esto es demasiado... Has hecho tanto por mi hijo y por mí...",
  ui_story_31000601_184_dialog_content = "No lo hago por tu bien. Como un <color=#FFB400>médico de los muertos</color>, mi trabajo aún no está terminado.",
  ui_story_31000601_185_dialog_content = "En cierto modo, transmitir las voces de los muertos es otra forma de preservar los derechos de quienes les sobreviven.",
  ui_story_31000601_186_dialog_content = "Ahora es el momento de hacer eso.",
  ui_story_31000601_187_dialog_content = "Nunca fuiste la madre de un asesino y no tenías motivos para seguir soportando todos estos rumores sin fundamento.",
  ui_story_31000601_188_dialog_content = "Sikare tiene toda la razón. Después de lo que tú y tu hijo habéis pasado, no deberíais tener que volver a insultaros así nunca más.",
  ui_story_31000601_189_dialog_content = "Además, dijiste que harías todo lo que estuviera a tu alcance para pagar lo que te pedíamos, ¿verdad?",
  ui_story_31000601_190_dialog_content = "Gracias... a los dos. Me aseguraré de contarle todo.",
  ui_story_31000601_191_dialog_content = "Bien. Ahora debo hacer una última cosa por ellos antes de irnos.",
  ui_story_31000601_192_dialog_content = "Faria, escucha mi llamada... Abre las puertas de la cripta y guía a estas desafortunadas almas a su lugar de descanso apropiado.",
  ui_story_31000601_193_dialog_content = "Creo que finalmente tendré una buena noche de sueño esta noche.",
  ui_story_31000601_194_dialog_content = "Que sus almas encuentren socorro en el abrazo de la Verdad.",
  ui_story_31000602_1_dialog_content = "<color=#e8d9bb>... Glup, glup!</color>",
  ui_story_31000602_2_dialog_content = "Ugh... Esto es asqueroso...",
  ui_story_31000602_3_dialog_content = "Apenas puedo moverme... Aunque siento como si estuviera nadando en agua, es como si no estuviera flotando en absoluto.",
  ui_story_31000602_4_dialog_content = "Solo... me hundo más profundo bajo esta marea negra, alejándome más de la superficie cada segundo...",
  ui_story_31000602_5_dialog_content = "¿Y qué son estas criaturas que me rodean? Nunca había visto nada como ellos antes...",
  ui_story_31000602_6_dialog_content = "Hermoso... extraño... espeluznante... ¿Estoy a punto de convertirme en su comida?",
  ui_story_31000602_7_dialog_content = "Sálvame... sálvame...",
  ui_story_31000602_8_dialog_content = "Bola de nieve... Bola de nieve...",
  ui_story_31000602_9_dialog_content = "¿Es esa una voz... llamándome?",
  ui_story_31000602_10_dialog_content = "Yo... gorjeo, gorgoteo... Estoy aquí... gorjeo, gorgoteo...",
  ui_story_31000602_11_dialog_content = "No tengas miedo, ya voy...",
  ui_story_31000602_12_dialog_content = "!",
  ui_story_31000602_13_dialog_content = "¿S-Sikare?",
  ui_story_31000602_14_dialog_content = "Soy yo.",
  ui_story_31000602_15_dialog_content = "Bola de nieve, ¿qué estás haciendo aquí?",
  ui_story_31000602_16_dialog_content = "Yo... gorjeo, gorgoteo... Yo...",
  ui_story_31000602_17_dialog_content = "Entiendo. Hablemos más una vez que lleguemos a la orilla.",
  ui_story_31000602_18_dialog_content = "Por favor, sigue la dirección hacia la que te estoy guiando. Siente la flotación de las olas.",
  ui_story_31000602_19_dialog_content = "Gorjeo, gorgoteo...",
  ui_story_31000602_20_dialog_content = "No tengas miedo, tomaré tu mano.",
  ui_story_31000602_21_dialog_content = "¡E-está bien!",
  ui_story_31000602_22_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_31000602_23_dialog_content = "¡Nosotros... finalmente logramos salir!",
  ui_story_31000602_24_dialog_content = "No, todavía no puedo dejarte salir.",
  ui_story_31000602_25_dialog_content = "No has respondido a mi pregunta anterior.",
  ui_story_31000602_26_dialog_content = "Dependiendo de tu respuesta, podría dejarte hundir en el pantano de nuevo.",
  ui_story_31000602_27_dialog_content = "¡O-Está bien! Por favor, solo escúchame!",
  ui_story_31000602_28_dialog_content = "¿Necesitas algo de mí, bola de nieve?",
  ui_story_31000602_29_dialog_content = "Es solo que... Te he visto encerrándote en tu habitación en el Coloso últimamente.",
  ui_story_31000602_30_dialog_content = "No tenemos muchos días de verano como este... ¿No quieres venir con todos los demás a un viaje a la playa?",
  ui_story_31000602_31_dialog_content = "Lo siento, pero no tengo tales planes.",
  ui_story_31000602_32_dialog_content = "Simplón, deberías saber que tales cosas no me interesan.",
  ui_story_31000602_33_dialog_content = "Sí, lo sé, pero ahora hay una promoción especial en el Tir' Hotel.",
  ui_story_31000602_34_dialog_content = "Hay otros Aurorianos como tú en el Coloso que básicamente nunca salen a divertirse.",
  ui_story_31000602_35_dialog_content = "Probablemente esta sea la mejor oportunidad que voy a tener para llevarte a todos a la playa para disfrutar del mar, el sol y... la ropa de baño...",
  ui_story_31000602_36_dialog_content = "Entonces, Bola de nieve, ¿quieres verme en un traje de baño, verdad?",
  ui_story_31000602_37_dialog_content = "No, ¡eso no es lo que quise decir en absoluto!",
  ui_story_31000602_38_dialog_content = "...",
  ui_story_31000602_39_dialog_content = "Entonces no tengo nada más que decirte. Por favor, vete.",
  ui_story_31000602_40_dialog_content = "<color=#e8d9bb>Algún tiempo después.</color>",
  ui_story_31000602_41_dialog_content = "Hemos ido a la playa y regresado, pero Sikare sigue solo en el Colossus...",
  ui_story_31000602_42_dialog_content = "Debería ir a verla, al menos para preguntar si quiere algún recuerdo!",
  ui_story_31000602_43_dialog_content = "¿Eh? ¿Por qué está abierta su puerta?",
  ui_story_31000602_44_dialog_content = "¿Disculpe... Eh? ¿Ella no está aquí?",
  ui_story_31000602_45_dialog_content = "Esto es... la caja negra de Sikare, Faria!",
  ui_story_31000602_46_dialog_content = "¿Realmente está bien dejarlo en el suelo así? Tal vez debería recogerlo por ella...",
  ui_story_31000602_47_dialog_content = "<color=#e8d9bb>¡Clac-clac! ¡Clac-clac!</color>",
  ui_story_31000602_48_dialog_content = "... ¿Se está moviendo esta cosa?",
  ui_story_31000602_49_dialog_content = "<color=#e8d9bb>¡Click-clac!</color>",
  ui_story_31000602_50_dialog_content = "¿Eh? ¡Ahhhhhhh—!",
  ui_story_31000602_51_dialog_content = "(Y así, me sumergí en la oscuridad, hundiéndome sin parar, cayendo en picado...)",
  ui_story_31000602_52_dialog_content = "(Para cuando recuperé la conciencia, ya estaba profundamente atrapado en este pantano, completamente incapaz de liberarme...)",
  ui_story_31000602_53_dialog_content = "Así que...",
  ui_story_31000602_54_dialog_content = "¿Es esa tu explicación?",
  ui_story_31000602_55_dialog_content = "Sí... Sí, y todo es cierto!",
  ui_story_31000602_56_dialog_content = "Solo pensé que podrías sentirte un poco solo en el Coloso.",
  ui_story_31000602_57_dialog_content = "¡Pensé que tal vez cambiarías de opinión y saldrías a jugar con todos!",
  ui_story_31000602_58_dialog_content = "Por favor, no uses ese tipo de pensamiento simplista para asumir mis pensamientos, como lo harían esos idiotas.",
  ui_story_31000602_59_dialog_content = "¿Parezco alguien tan voluble?",
  ui_story_31000602_60_dialog_content = "Lo siento... No quise decir eso.",
  ui_story_31000602_61_dialog_content = "¿Fui adelante y terminé en un lugar donde no debería estar?",
  ui_story_31000602_62_dialog_content = "Si realmente te gustaría saber la respuesta a esa pregunta...",
  ui_story_31000602_63_dialog_content = "¿Qué tal si me acompañas en un recorrido por este lugar?",
  ui_story_31000602_64_dialog_content = "Veo tanto miedo como curiosidad en tus ojos. Debes estar muy interesado en este lugar, ¿verdad?",
  ui_story_31000602_65_dialog_content = "Sí. Este pantano, y las criaturas y plantas que hay aquí...",
  ui_story_31000602_66_dialog_content = "Nunca había visto algo como ellos. ¿Podría ser este lugar...",
  ui_story_31000602_67_dialog_content = "Eso es correcto. Esta es una tumba dentro de la Cripta Estrellada.",
  ui_story_31000602_68_dialog_content = "Esas extrañas criaturas que has visto son los guardianes aquí.",
  ui_story_31000602_69_dialog_content = "Cuando te estabas hundiendo en el pantano antes, si hubieran sentido alguna hostilidad...",
  ui_story_31000602_70_dialog_content = "Habrían hecho todo lo posible para eliminarte, el intruso.",
  ui_story_31000602_71_dialog_content = "Entonces... ¿Acabo de escapar por poco con mi vida ahora mismo?",
  ui_story_31000602_72_dialog_content = "Tenga la seguridad de que saben que no tienes malas intenciones y no intentarán atentar contra tu vida.",
  ui_story_31000602_73_dialog_content = "Entonces, Sikare, eso significa... ¡sabían desde el principio que yo no era un intruso!",
  ui_story_31000602_74_dialog_content = "Por supuesto, también confían en su propio juicio.",
  ui_story_31000602_75_dialog_content = "Algunos saqueadores de tumbas son expertos en ocultar sus intenciones, pero claramente te falta tal astucia, simplón.",
  ui_story_31000602_76_dialog_content = "Tu curiosidad es casi desbordante, ahogando cualquier rastro de hostilidad.",
  ui_story_31000602_77_dialog_content = "¿Es tan obvio?",
  ui_story_31000602_78_dialog_content = "No es algo malo, Bola de Nieve.",
  ui_story_31000602_79_dialog_content = "Para un verdadero explorador, estas vistas extrañas y fantásticas son tesoros por derecho propio.",
  ui_story_31000602_80_dialog_content = "...Tienes razón en eso.",
  ui_story_31000602_81_dialog_content = "Ahora que he tenido la oportunidad de mirar bien a mi alrededor, el paisaje aquí es verdaderamente hermoso.",
  ui_story_31000602_82_dialog_content = "Una belleza misteriosa, etérea... Es tan diferente de las playas concurridas y ruidosas del verano.",
  ui_story_31000602_83_dialog_content = "¿Caminas a menudo por aquí, Sikare?",
  ui_story_31000602_84_dialog_content = "¿Caminar? \"Patrulla\" sería un verbo más apropiado.",
  ui_story_31000602_85_dialog_content = "Como la patrulla de hoy, que produjo una captura muy especial—",
  ui_story_31000602_86_dialog_content = "¿Y-Yo? ¿Así que la Caja Negra me atrapó como si fuera su presa?",
  ui_story_31000602_87_dialog_content = "Uh, hablando de eso... ¿No deberíamos ocuparnos de la Caja Negra en tu habitación?",
  ui_story_31000602_88_dialog_content = "¿Lidiar con eso?",
  ui_story_31000602_89_dialog_content = "Sí, después de todo...",
  ui_story_31000602_90_dialog_content = "¡No quiero molestarte para que rescates a alguien más!",
  ui_story_31000602_91_dialog_content = "¿Estás preocupado por molestarme?",
  ui_story_31000602_92_dialog_content = "No creo que eso sea lo que realmente estás pensando, Snowball...",
  ui_story_31000602_93_dialog_content = "¿Te preocupa que si tus amigos Aurorianos irrumpen imprudentemente, los resultados serían problemáticos para ti, sí?",
  ui_story_31000602_94_dialog_content = "¡Por supuesto, sería mejor no ser molestado por otras personas!",
  ui_story_31000602_95_dialog_content = "¿No quieres que te molesten?",
  ui_story_31000602_96_dialog_content = "Parece que realmente te gusta el paisaje aquí, Snowball.",
  ui_story_31000602_97_dialog_content = "¿No quieres compartirlo con los demás? Es raro escucharte demostrar tal egoísmo...",
  ui_story_31000602_98_dialog_content = "No me refería a eso...",
  ui_story_31000602_99_dialog_content = "¿No dijiste que prefieres una vida pacífica?",
  ui_story_31000602_100_dialog_content = "Si los otros Aurorianos realmente vienen aquí, este lugar no será diferente a un complejo de playa.",
  ui_story_31000602_101_dialog_content = "¿Has considerado este aspecto? Una justificación digna de alguien a quien Lady Victoria estima tanto.",
  ui_story_31000602_102_dialog_content = "Pero permíteme aclarar algo, no tengo quejas sobre ninguno de nuestros compañeros, simplemente no me gustan los ambientes ruidosos.",
  ui_story_31000602_103_dialog_content = "Si alguien me acompañara en silencio, sería mejor que estar solo, hasta cierto punto.",
  ui_story_31000602_104_dialog_content = "¿D-De veras?",
  ui_story_31000602_105_dialog_content = "De hecho, esta es también la primera vez que tengo la oportunidad de apreciar lo hermoso que es aquí en la Cripta Estrellada. ¡Nunca había visto un lugar como este antes!",
  ui_story_31000602_106_dialog_content = "Si no te importa, ¡me gustaría venir aquí más a menudo para pasar el rato contigo!",
  ui_story_31000602_107_dialog_content = "es solo...",
  ui_story_31000602_108_dialog_content = "¿Algún problema, Bola de Nieve?",
  ui_story_31000602_109_dialog_content = "Ojalá hubiera una forma más normal de entrar a este lugar... ¡No quiero encontrarme hundiéndome en ese pantano por segunda vez!",
  ui_story_31000602_110_dialog_content = "No te preocupes. No importa por qué entrada vengas, o qué tumba entres...",
  ui_story_31000602_111_dialog_content = "Vendré a buscarte de inmediato.",
  ui_story_31000602_112_dialog_content = "Después de todo, la verdadera entrada siempre está en mis manos.",
  ui_story_31000602_113_dialog_content = "Oh... ¿Ya has recuperado tu Caja Negra? ¿Cuándo lo hiciste—",
  ui_story_31000602_114_dialog_content = "¿Qué estás pensando, bola de nieve?",
  ui_story_31000602_115_dialog_content = "¿Tú... Entraste aquí después de mí?",
  ui_story_31000602_116_dialog_content = "Interesante. ¿Por qué piensas eso?",
  ui_story_31000602_117_dialog_content = "Bueno, no tuviste tiempo para volver y conseguir la Caja Negra, y...",
  ui_story_31000602_118_dialog_content = "Normalmente no te cambiarías a un <color=#FFB400>traje de baño</color> durante tu patrulla, ¿verdad? Entonces, ¿eso significa...",
  ui_story_31000602_119_dialog_content = "So, Snowball, you wish to see me in a swimsuit, do you?",
  ui_story_31000602_120_dialog_content = "No, that's not what I meant at all!",
  ui_story_31000602_121_dialog_content = "¿Es esto por lo que dije antes?",
  ui_story_31000602_122_dialog_content = "Por favor, no uses ese tipo de pensamiento simplista para asumir mis motivos, como lo harían esos idiotas.",
  ui_story_31000602_123_dialog_content = "Esto es simplemente el resultado de mi propia voluntad, o quizás un capricho.",
  ui_story_31000602_124_dialog_content = "No quiero ser visto por esos idiotas, ni deseo ser juzgado por ellos.",
  ui_story_31000602_125_dialog_content = "Así que solo me cambio a mi traje de baño aquí. ¿Entendido?",
  ui_story_31000602_126_dialog_content = "Pero... realmente te queda bien.",
  ui_story_31000602_127_dialog_content = "En comparación con esas criaturas mágicas y plantas...",
  ui_story_31000602_128_dialog_content = "Incluso diría que eres más hermosa.",
  ui_story_31000602_129_dialog_content = "...",
  ui_story_31000602_130_dialog_content = "¿Cuándo te permití enfocar tu curiosidad en mí?",
  ui_story_31000602_131_dialog_content = "Incluso sin albergar hostilidad, si bajas la guardia y violas las leyes de la cripta...",
  ui_story_31000602_132_dialog_content = "Es posible que aún te encuentres arrastrado al abismo por estos oscuros tentáculos, convirtiéndote en una decoración permanente aquí en la tumba.",
  ui_story_31000602_133_dialog_content = "¿No es eso ir un poco demasiado lejos?",
  ui_story_31000602_134_dialog_content = "¿Temor?",
  ui_story_31000602_135_dialog_content = "Un poco... y realmente algo preocupado!",
  ui_story_31000602_136_dialog_content = "Tu reacción, Snowball... es realmente bastante linda.",
  ui_story_31000602_137_dialog_content = "No te preocupes, te protegeré. <size=30>Después de todo, el único que puede liberarme de los grilletes de la cripta...</size>",
  ui_story_31000602_138_dialog_content = "¿Qué?",
  ui_story_31000602_139_dialog_content = "Dije... Acércate. Más cerca.",
  ui_story_31000602_140_dialog_content = "Para tu seguridad, Snowball, mientras estés en la cripta, debes <color=#FFB400>siempre</color> permanecer cerca de mí.",
  ui_story_31000602_141_dialog_content = "¿Entender?",
  ui_story_31000602_142_dialog_content = "¡De acuerdo, no te dejaré! ¡Te prometo que me quedaré a tu lado!"
}
return config
